// text render function starts here;
const text_container = document.querySelector('#text-container')
function textRender(text) {
    const words = text.split(' ')
    let html_codes = ''
    let i = 0
    words.forEach(word => {
        html_codes += '<span class="word">'
        for (let j = 0; j < word.length; j++) {
            html_codes += `<span id="letter${i}" class="letter ">${word[j]}</span>`
            i++
        };
        html_codes += '</span>'

        html_codes += `<span id="letter${i}" class="space "> </span>`
        i++
    });
    text_container.innerHTML = html_codes
}

textRender(text)
//text render function ends here;



//main logic starts here;


function selectFirstLetter() {
    current = 0
    id = "#letter" + current
    const firstElement = document.querySelector(id)
    firstElement.classList.add('active')
}
selectFirstLetter()

function handleKeyPress(event) {
    if (!isTimerStarted) {
        // sound effect for timer start
        const select_time = document.querySelector('#time-select')
        const totalSec = parseInt(select_time.value) - 1
        startTimer(totalSec)
        isTimerStarted = true
    }
    if(current >= text.length){
        gameOverSound.play()
        endOfTest()
        return
    }
    const activeElement = document.querySelector('.active')
    event.preventDefault()
    const keyPressed = event.key
    const actualValue = text[current]

    if (keyPressed !== 'Shift') {
        if (keyPressed === 'Backspace') {
            if (current > 0) {
                if(soundOn){
                    soundBackspacePressed.play()
                }
                totalPressed--
                totalKeyPressedElement.innerHTML = `<p class="result">${totalPressed}</p> <p>Total Key Pressed</p>`
                const activeElement = document.querySelector('.active')
                activeElement.classList.remove('active')
                current--
                if (activeElement.classList.contains('space')) {
                    wordCount--
                }

                id = "#letter" + current
                const prevElement = document.querySelector(id)

                if (prevElement.classList.contains('wrong')) {
                    totalWrongPressed--
                    totalWrongKeyPressedElement.innerHTML = `<p>Total Wrong Pressed</p><p class="result">${totalWrongPressed}</p>`
                    prevElement.classList.remove('wrong')
                }
                else if (prevElement.classList.contains('passed')) {
                    totalRigthPressed--
                    totalRightKeyPressedElement.innerHTML = `<p>Total Right Pressed</p><p class="result">${totalRigthPressed}</p>`
                    prevElement.classList.remove('passed')
                }
                prevElement.classList.add('active')
                // console.log(prevElement.offsetTop)
                scrollContainer.scrollTop = prevElement.offsetTop - 299
            }
            else {
                soundWrongPressed.play()
            }
        }
        else {
            totalPressed++
            totalKeyPressedElement.innerHTML = `<p class="result">${totalPressed}</p> <p>Total Key Pressed</p>`

            if (activeElement.classList.contains('space')) {
                wordCount++
            }
            if (keyPressed === actualValue || (actualValue === ' ' && keyPressed === 'Enter')) {
                if(soundOn){
                    soundRightPressed.play()
                }
                totalRigthPressed++
                totalRightKeyPressedElement.innerHTML = `<p>Total Right Pressed</p><p class="result">${totalRigthPressed}</p>`
                activeElement.classList.remove('active')
                activeElement.classList.add('passed')
            }
            else {
                if(soundOn){
                    soundWrongPressed.play()
                }
                totalWrongPressed++
                totalWrongKeyPressedElement.innerHTML = `<p>Total Wrong Pressed</p><p class="result">${totalWrongPressed}</p>`
                activeElement.classList.remove('active')
                activeElement.classList.add('wrong')
            }
            current++
            id = "#letter" + current
            const nextElement = document.querySelector(id)
            nextElement.classList.add('active')
            // console.log(nextElement.offsetTop) 
            scrollContainer.scrollTop = nextElement.offsetTop - 299

        }
    }
}

function startTyping() {
    document.addEventListener('keydown', handleKeyPress)
}
startTyping()
// main logic ends here;



